/**
 * sensitivity-rules.ts — 诊断隐私控制
 *
 * 对标 Claw-Code permissions.rs 的层级可见性：
 *   - 敏感字段自动检测（薪资/绩效/健康/身份）
 *   - 按 DiagnosisPermissionLevel 脱敏
 *   - 字段级标注（redact / anonymize / allow）
 *   - 审计日志记录每次脱敏决策
 *
 * 敏感度分类：
 *   PII        — 个人身份信息（姓名、手机、邮箱）
 *   FINANCIAL  — 财务数据（薪资、股权、奖金）
 *   PERFORMANCE — 绩效评估（评级、360 反馈原文）
 *   HEALTH     — 健康/心理状态
 *   CONFLICT   — 人际冲突细节
 *   STRATEGIC  — 战略/商业机密
 */
import { DiagnosisPermissionLevel } from './types';
/** 敏感度类别 */
export type SensitivityCategory = 'pii' | 'financial' | 'performance' | 'health' | 'conflict' | 'strategic';
/** 脱敏动作 */
export type RedactAction = 'allow' | 'anonymize' | 'redact' | 'summarize';
/** 敏感字段检测结果 */
export interface SensitivityMatch {
    /** 字段名或路径 */
    field: string;
    /** 敏感度类别 */
    category: SensitivityCategory;
    /** 匹配到的敏感关键词 */
    matchedKeyword: string;
    /** 所需的最低查看权限 */
    minLevel: DiagnosisPermissionLevel;
}
/** 脱敏规则 */
export interface SensitivityRule {
    /** 规则名 */
    name: string;
    /** 敏感度类别 */
    category: SensitivityCategory;
    /** 触发关键词（支持中文和英文） */
    keywords: string[];
    /** 最低查看权限 */
    minLevel: DiagnosisPermissionLevel;
    /** 低于权限时的默认动作 */
    defaultAction: RedactAction;
}
/** 脱敏后的字段 */
export interface RedactedField {
    field: string;
    originalCategory: SensitivityCategory;
    action: RedactAction;
    /** 脱敏后的值（redact = "***"，anonymize = 替换标识符，summarize = 摘要） */
    sanitizedValue?: string;
}
/** 脱敏审计记录 */
export interface RedactionAuditEntry {
    field: string;
    category: SensitivityCategory;
    action: RedactAction;
    requesterLevel: DiagnosisPermissionLevel;
    requiredLevel: DiagnosisPermissionLevel;
    timestamp: string;
}
/** 扫描字段名，返回匹配的敏感规则 */
export declare function detectSensitiveFields(fieldNames: string[], customRules?: SensitivityRule[]): SensitivityMatch[];
/** 扫描文本内容中是否包含敏感关键词 */
export declare function scanContentForSensitivity(content: string, customRules?: SensitivityRule[]): SensitivityMatch[];
/** 对单个字段值执行脱敏 */
export declare function redactField(field: string, value: string, match: SensitivityMatch, requesterLevel: DiagnosisPermissionLevel): RedactedField;
/** 批量脱敏对象中的所有敏感字段 */
export declare function redactObject(obj: Record<string, unknown>, requesterLevel: DiagnosisPermissionLevel, customRules?: SensitivityRule[]): {
    redacted: Record<string, unknown>;
    audit: RedactionAuditEntry[];
};
/** 获取内置规则列表（供扩展用） */
export declare function getBuiltinRules(): SensitivityRule[];
/** 添加自定义敏感规则 */
export declare function createCustomRule(name: string, category: SensitivityCategory, keywords: string[], minLevel: DiagnosisPermissionLevel, defaultAction?: RedactAction): SensitivityRule;
